<div x-data="complaintShow({{ $id }})" x-init="init()" x-cloak><div class="mb-7 flex items-end justify-between"><div><p class="text-sm text-slate-600">Informasi laporan masyarakat</p><h2 class="mt-1 text-2xl font-semibold text-navy-900" x-text="item ? code(item) : 'Detail Aduan'">Detail Aduan</h2></div><a href="{{ route('complaints.index') }}" class="action-button">Kembali</a></div><div x-show="error" class="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" x-text="error"></div><div x-show="item" class="grid gap-5 lg:grid-cols-[minmax(0,1fr)_360px]"><section class="rounded-2xl border border-border bg-white p-6 shadow-sm"><dl class="grid gap-5 sm:grid-cols-2"><div><dt class="detail-label">Jenis aset</dt><dd class="detail-value" x-text="type(item)"></dd></div><div><dt class="detail-label">Status</dt><dd class="detail-value" x-text="item?.status_aduan"></dd></div><div><dt class="detail-label">Kategori</dt><dd class="detail-value" x-text="item?.kategori_aduan || '-' "></dd></div><div><dt class="detail-label">Tanggal</dt><dd class="detail-value" x-text="item?.tanggal_aduan || '-' "></dd></div><div class="sm:col-span-2"><dt class="detail-label">Pelapor</dt><dd class="detail-value" x-text="`${item?.nama_pelapor || '-'} — ${item?.kontak_pelapor || 'Kontak tidak dicantumkan'}`"></dd></div><div class="sm:col-span-2"><dt class="detail-label">Lokasi</dt><dd class="detail-value" x-text="item?.alamat_kejadian || item?.aset?.alamat || '-' "></dd></div><div class="sm:col-span-2"><dt class="detail-label">Deskripsi</dt><dd class="mt-1 whitespace-pre-line text-sm text-slate-700" x-text="item?.deskripsi || '-' "></dd></div></dl><div x-show="success" class="mb-4 rounded-lg bg-teal-50 px-3 py-2 text-sm text-teal-800" x-text="success"></div><div class="mt-6"><label class="field-label" for="status_aduan">Perbarui status</label><div class="flex gap-2"><select id="status_aduan" x-model="status" class="field-input"><option value="baru">Baru</option><option value="diproses">Diproses</option><option value="selesai">Selesai</option></select><button type="button" @click="update" :disabled="saving" class="action-button-primary">Simpan</button></div></div></section><section class="mt-5 rounded-2xl border border-border bg-white p-5 shadow-sm"><h3 class="font-semibold text-navy-900">Riwayat status</h3><div class="mt-4 space-y-3"><template x-for="history in (item?.histories || [])" :key="history.id"><div class="border-l-2 border-teal-400 pl-4 text-sm"><p class="font-medium text-slate-700" x-text="`${history.status_lama || '-'} → ${history.status_baru}`"></p><p class="text-xs text-slate-500" x-text="`${history.pengubah?.name || '-'} · ${history.created_at || '-'}`"></p><p x-show="history.keterangan" class="text-xs text-slate-600" x-text="history.keterangan"></p></div></template><p x-show="historyError" class="mt-3 text-sm text-red-600" x-text="historyError"></p><p x-show="!historyError && item && !item?.histories?.length" class="mt-3 text-sm text-slate-500">Belum ada perubahan status.</p></div></section><aside class="rounded-2xl border border-border bg-white p-5 shadow-sm"><div id="complaint-detail-map" class="h-64 overflow-hidden rounded-xl bg-[#dbe7e5]"></div><template x-if="item?.foto"><a :href="photoUrl(item.foto)" target="_blank" rel="noreferrer" class="mt-4 block text-sm font-semibold text-teal-700 underline">Lihat foto pendukung</a></template></aside></div></div>
<script>const complaintApiBase = @json(url("/api"));
function complaintShow(id){return{item:null,status:'baru',saving:false,success:'',error:'',historyError:'',map:null,marker:null,async init(){try{const response=await window.axios.get(`${complaintApiBase}/aduan/${id}`); let data=response?.data ?? response; while(data?.data && !data.id) data=data.data; this.item=data; this.item.histories=Array.isArray(data.histories)?data.histories:(Array.isArray(data.history)?data.history:[]); this.status=this.item.status_aduan; this.initMap()}catch(e){this.error=e.response?.status===401?'Sesi login tidak ditemukan.':e.response?.status===404?'Aduan tidak ditemukan.':e.response?.data?.message||'Gagal memuat detail aduan.'}},initMap(){this.map=window.Leaflet.map('complaint-detail-map',{center:[-7.6786,109.6565],zoom:11,scrollWheelZoom:false});window.Leaflet.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(this.map);const lat=Number(this.item.latitude||this.item.aset?.latitude),lng=Number(this.item.longitude||this.item.aset?.longitude);if(Number.isFinite(lat)&&Number.isFinite(lng)){this.marker=window.Leaflet.marker([lat,lng],{icon:window.locationMarkerIcon(),title:'Lokasi aduan'}).addTo(this.map);this.marker.bindPopup(`<strong>${this.code(this.item)}</strong><br>${this.type(this.item)}<br>Status: ${this.item.status_aduan}`);this.map.setView([lat,lng],14)}setTimeout(()=>this.map.invalidateSize(),100)},async update(){this.saving=true;try{this.item=(await window.axios.put(`${complaintApiBase}/aduan/${id}`,{status_aduan:this.status})).data; this.status=this.item.status_aduan; this.success='Status aduan berhasil diperbarui.'; setTimeout(()=>this.success='',3000)}catch(e){this.error=e.response?.data?.message||'Gagal memperbarui status.'}finally{this.saving=false}},code(x){return`ADUAN-${String(x.id).padStart(6,'0')}`},type(x){return String(x.aset_type||'').includes('Rambu')?'Rambu':'LPJU'},photoUrl(p){return String(p).startsWith('/')?p:`/storage/${p}`}}}</script>
